shader:
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
vec4 cell(vec2 uv){
  vec2 c=floor(uv*u_grid);
  float speed=5.0+hash(vec2(c.x,1.0))*9.0, len=6.0+hash(vec2(c.x,2.0))*22.0;
  float span=u_grid.y+len+hash(vec2(c.x,3.0))*50.0;
  float d=mod(u_time*speed+hash(vec2(c.x,4.0))*span,span)-c.y;
  float b=d>=0.0&&d<len?1.0-d/len:0.0;
  float near=u_strength*smoothstep(0.2,0.0,length((uv-u_pointer)*vec2(u_aspect,1.0)))*step(u_idle,2.0);
  float ring=0.0;
  for(int i=0;i<8;i++){vec3 k=u_clicks[i];
    ring=max(ring,smoothstep(0.025,0.0,abs(length((uv-k.xy)*vec2(u_aspect,1.0))-k.z*0.5))*max(0.0,1.0-k.z/1.6));}
  b=max(max(b,near*0.35),ring);
  if(b<0.03)return vec4(0.0);
  float flip=floor(u_time*(1.5+near*25.0)+hash(c)*9.0);
  float glyph=1.0+floor(hash(c+flip*vec2(1.7,9.2))*41.0);
  vec3 color=d>=0.0&&d<1.0?vec3(0.8,1.0,0.8):vec3(0.0,1.0,0.27)*b;
  return vec4(color,glyph/41.0);
}
